from math import inf 
from collections import deque
from heapq import * 

def solver(grid): 
    scores = [[inf for _ in grid[0]] for _ in grid]
    pq = deque()
    for i in range(len(grid)): 
        for j in range(len(grid[0])): 
            if grid[i][j] != 1: 
                continue 
            pq.append([i, j, 0])
    while pq: 
        x, y, val = pq.popleft() 
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or scores[x][y] <= val: 
            continue 
        scores[x][y] = val 
        for move in [-1, 1]: 
            pq.append([x + move, y, val + 1])
            pq.append([x, y + move, val + 1])
    visited = set()
    pq = [] 
    heappush(pq, [-scores[0][0], 0, 0])
    while pq: 
        val, x, y = heappop(pq)
        if (x, y) in visited or x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]): 
            continue 
        visited.add((x, y))
        val = max(val, -scores[x][y])
        if x == len(grid) - 1 and y == len(grid[0]) - 1: 
            return -val 
        for move in [-1, 1]: 
            heappush(pq, [val, x + move, y])
            heappush(pq, [val, x, y + move])
                

